import{_ as t,a as r,o as a,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Delete Product Review","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-product-review","title":"Delete Product Review","description":"Delete an existing product review.","request":"DELETE /api/shop/reviews/1\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 204 No Content\\n","commonErrors":[{"error":"403 Forbidden — This review was not written by you","cause":"The review belongs to another customer, or to a guest","solution":"A review can only be removed by the customer who wrote it"},{"error":"403 Forbidden — Please login to manage your review","cause":"No customer Bearer token was sent","solution":"Log the customer in and retry"},{"error":"404 Not Found","cause":"No review carries that ID","solution":"Use an ID from the customer's own reviews"}]}]},"headers":[],"relativePath":"api/rest-api/shop/product-reviews/delete-product-review.md","filePath":"api/rest-api/shop/product-reviews/delete-product-review.md","lastUpdated":1787725411000}`),i={name:"api/rest-api/shop/product-reviews/delete-product-review.md"};function s(d,e,n,l,h,c){return a(),r("div",null,e[0]||(e[0]=[o('<h1 id="delete-product-review" tabindex="-1">Delete Product Review <a class="header-anchor" href="#delete-product-review" aria-label="Permalink to &quot;Delete Product Review&quot;">​</a></h1><p>Delete an existing product review. Only the review author can delete their own review.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DELETE /api/shop/reviews/{reviewId}</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (review author required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>reviewId</code></td><td>integer</td><td>Yes</td><td>The review to remove. No product ID is part of the path.</td></tr></tbody></table><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p><code>204 No Content</code> with an empty body. There is no confirmation message — the status is the confirmation.</p><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><p>A review may only be removed by the customer who wrote it, checked against the stored author:</p><ul><li>Another customer&#39;s review answers <code>403</code>.</li><li>A review submitted by a guest has no author and can never be removed through the API — also <code>403</code>.</li><li>Deletion is permanent; the row is not soft-deleted and cannot be restored.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Delete your review&quot; on a product page</strong> — call with the review ID and drop the row locally; the empty body leaves nothing to re-render from.</li><li><strong>Replace a review</strong> — there is no resubmit flow, so removing and creating again is how a shopper starts over. The new review returns to <code>pending</code>.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Confirm before calling</strong> — the removal is immediate and irreversible.</li><li><strong>Prefer <a href="/api/rest-api/shop/product-reviews/update-product-review.html">Update</a> for corrections</strong> — editing keeps an approved review live, while deleting and recreating sends it back into moderation.</li><li><strong>Do not parse a body</strong> — a <code>204</code> carries none.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/product-reviews/get-product-review.html">Get Product Review</a> — one review by id, whatever its status</li><li><a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a> — submit a review; it starts as pending</li><li><a href="/api/rest-api/shop/product-reviews/update-product-review.html">Update Product Review</a> — edit the customer&#39;s own review</li></ul>',19)]))}const w=t(i,[["render",s]]);export{u as __pageData,w as default};
